function makeMaterial(m: Mat): THREE.MeshPhysicalMaterial {
  // Mirrors createSculptMaterial's textureless branch (sRGB setStyle, binary metalness, sheen).
  return new THREE.MeshPhysicalMaterial({
    color: new THREE.Color().setStyle(m.c, THREE.SRGBColorSpace),
    roughness: m.r,
    metalness: m.mt,
    sheen: m.sh ?? 0,
    sheenColor: new THREE.Color('#ffffff'),
    sheenRoughness: m.shr ?? 1,
    emissive: new THREE.Color(m.e ?? '#000000'),
  });
}

function partGeometry(part: Part): THREE.BufferGeometry {
  const g = part.g!;
  if (g[0] === 's') return new THREE.SphereGeometry(0.5, 16, 10);
  if (g[0] === 'l') return buildLatheGeometry({ points: g[1], segments: g[2] });
  return buildTaperedSweepGeometry({
    stations: g[1].map(([position, rx, rz]) => ({ position, rx, rz, twist: 0 })),
    radialSegments: g[2],
    capEnds: true,
  });
}

export function createPaoModel(options: ProceduralModelOptions = {}): THREE.Group {
  const root = new THREE.Group();
  root.name = 'Pao';
  const rootPivot = new THREE.Group();
  rootPivot.name = 'root__pivot';
  root.add(rootPivot);
  const nodes: Record<string, THREE.Object3D> = { root: rootPivot };
  const meshes: Record<string, THREE.Mesh> = {};
  const materials: Record<string, THREE.MeshPhysicalMaterial> = {};
  for (const [id, m] of Object.entries(MATERIALS)) materials[id] = makeMaterial(m);

  for (const part of PARTS) {
    const node = new THREE.Group();
    node.name = part.id + '__pivot';
    const endpoint = part.a
      ? makeAttachmentEndpoint({ localStart: part.a[0], localEnd: part.a[1], baseRadius: part.a[2], endRadius: part.a[3] })
      : null;
    if (endpoint) node.position.copy(endpoint.start);
    else node.position.set(...part.pos);
    node.rotation.set(...part.rot);
    (nodes[part.p] ?? root).add(node);
    nodes[part.id] = node;

    const geometry = endpoint
      ? new THREE.CylinderGeometry(endpoint.endRadius, endpoint.baseRadius, endpoint.length, 8, 4)
      : partGeometry(part);
    if (!endpoint && part.s) geometry.scale(...part.s);
    let material = materials[part.m];
    if (part.vp) {
      applyVertexPaint(geometry, part.vp.baseColor, part.vp.regions);
      material = material.clone();
      material.vertexColors = true;
      material.color.setRGB(1, 1, 1);
    }
    const mesh = new THREE.Mesh(geometry, material);
    mesh.name = part.id;
    if (endpoint) {
      mesh.position.copy(endpoint.midpoint);
      mesh.quaternion.copy(endpoint.quaternion);
    }
    mesh.castShadow = options.castShadow ?? true;
    mesh.receiveShadow = options.receiveShadow ?? true;
    node.add(mesh);
    meshes[part.id] = mesh;
  }

  for (const [id, against, clearance, maxPush] of STAND_PROUD) {
    if (meshes[id] && nodes[against]) applyStandProud(meshes[id].geometry, meshes[id], nodes[against], HEAD_RINGS, clearance, maxPush);
  }
  root.userData.sculptRuntime = { nodes, meshes } satisfies ProceduralModelRuntime;
  return root;
}
